<template><div class="page-shell"><header class="page-header"><div><h2>教学资源</h2><p>维护课程课件、文件地址和外部参考链接</p></div><button class="primary" @click="openCreate">新增资源</button></header><section class="filters"><input v-model.trim="keyword" placeholder="搜索资源名称"/><select v-model="courseId"><option value="">全部课程</option><option v-for="c in courses" :key="c.courseId" :value="c.courseId">{{ c.courseName }}</option></select><select v-model="type"><option value="">全部类型</option><option v-for="t in types" :key="t.value" :value="t.value">{{ t.label }}</option></select><button @click="load">查询</button></section><p v-if="message" class="error">{{ message }}</p><section class="card"><div v-if="loading" class="state">正在加载…</div><div v-else-if="resources.length===0" class="state">暂无教学资源</div><div v-else class="scroll"><table><thead><tr><th>资源</th><th>类型</th><th>关联课程</th><th>大小</th><th>上传人</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in resources" :key="r.resourceId"><td><strong>{{ r.resourceName }}</strong><small>{{ r.resourceNo }}</small></td><td><span class="tag">{{ resourceTypeLabel(r.resourceType) }}</span></td><td>{{ r.courseName }}</td><td>{{ size(r.fileSize) }}</td><td>{{ r.uploadedByName||'—' }}</td><td>{{ time(r.createdAt) }}</td><td><div class="actions"><a v-if="r.fileUrl||r.externalUrl" :href="r.fileUrl||r.externalUrl||'#'" target="_blank" rel="noopener">打开</a><button @click="openEdit(r)">编辑</button><button @click="remove(r)">删除</button></div></td></tr></tbody></table></div></section>
<teleport to="body"><div v-if="dialog" class="overlay" @click.self="dialog=false"><section class="modal"><header><div><h3>{{ editingId?'编辑资源':'新增资源' }}</h3><p>当前文件服务未接入，请填写可访问的文件地址或外部链接</p></div><button @click="dialog=false">×</button></header><div class="body"><label><span>资源名称 *</span><input v-model.trim="form.resourceName" /></label><label><span>关联课程 *</span><select v-model="form.courseId" :disabled="Boolean(editingId)"><option :value="0" disabled>请选择</option><option v-for="c in courses" :key="c.courseId" :value="c.courseId">{{ c.courseName }}</option></select></label><label><span>资源类型 *</span><select v-model="form.resourceType"><option v-for="t in types" :key="t.value" :value="t.value">{{ t.label }}</option></select></label><label v-if="fileBased"><span>文件地址 *</span><input v-model.trim="form.fileUrl" placeholder="https://..." /></label><label v-else><span>外部链接 *</span><input v-model.trim="form.externalUrl" placeholder="https://..." /></label><label><span>文件大小（字节）</span><input v-model.number="form.fileSize" type="number" min="0" /></label><label><span>排序号</span><input v-model.number="form.sortNo" type="number" min="0" /></label><p v-if="formError" class="error">{{ formError }}</p></div><footer><button @click="dialog=false">取消</button><button class="primary" :disabled="saving" @click="save">保存</button></footer></section></div></teleport></div></template>
<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{createResource,deleteResource,getCoursePage,getResourcePage,resourceTypeLabel,updateResource,type CourseListItem,type ResourceItem,type ResourceType}from'../../utils/teachingApi';const resources=ref<ResourceItem[]>([]),courses=ref<CourseListItem[]>([]),loading=ref(false),saving=ref(false),dialog=ref(false),editingId=ref(0),keyword=ref(''),courseId=ref<number|''>(''),type=ref<ResourceType|''>(''),message=ref(''),formError=ref('');const types=[{value:1 as ResourceType,label:'PPT'},{value:2 as ResourceType,label:'Word'},{value:3 as ResourceType,label:'PDF'},{value:4 as ResourceType,label:'视频链接'},{value:5 as ResourceType,label:'参考链接'},{value:6 as ResourceType,label:'其他'}];const form=reactive({courseId:0,resourceName:'',resourceType:1 as ResourceType,fileUrl:'',externalUrl:'',fileSize:0,sortNo:0});const fileBased=computed(()=>[1,2,3,6].includes(form.resourceType));const err=(e:unknown)=>e instanceof Error?e.message:'操作失败';const size=(n?:number|null)=>!n?'—':n>=1048576?`${(n/1048576).toFixed(1)} MB`:n>=1024?`${(n/1024).toFixed(1)} KB`:`${n} B`;const time=(v:string)=>v?.replace('T',' ').slice(0,16)||'—';async function load(){loading.value=true;try{const p=await getResourcePage({pageNum:1,pageSize:500,keyword:keyword.value||undefined,courseId:courseId.value===''?undefined:courseId.value,resourceType:type.value===''?undefined:type.value});resources.value=p.records}catch(e){message.value=err(e)}finally{loading.value=false}}function clear(){Object.assign(form,{courseId:0,resourceName:'',resourceType:1,fileUrl:'',externalUrl:'',fileSize:0,sortNo:0});formError.value=''}function openCreate(){clear();editingId.value=0;dialog.value=true}function openEdit(r:ResourceItem){Object.assign(form,{courseId:r.courseId,resourceName:r.resourceName,resourceType:r.resourceType,fileUrl:r.fileUrl||'',externalUrl:r.externalUrl||'',fileSize:r.fileSize||0,sortNo:r.sortNo});editingId.value=r.resourceId;formError.value='';dialog.value=true}async function save(){if(!form.resourceName||!form.courseId||(fileBased.value?!form.fileUrl:!form.externalUrl)){formError.value='请填写资源名称、课程和对应的资源地址';return}saving.value=true;const common={resourceName:form.resourceName,resourceType:form.resourceType,fileUrl:fileBased.value?form.fileUrl:undefined,externalUrl:fileBased.value?undefined:form.externalUrl,fileSize:form.fileSize||undefined,sortNo:form.sortNo};try{if(editingId.value)await updateResource(editingId.value,common);else await createResource({courseId:form.courseId,...common});dialog.value=false;await load()}catch(e){formError.value=err(e)}finally{saving.value=false}}async function remove(r:ResourceItem){if(!confirm(`确认删除“${r.resourceName}”？`))return;try{await deleteResource(r.resourceId);await load()}catch(e){message.value=err(e)}}onMounted(async()=>{try{courses.value=(await getCoursePage({pageNum:1,pageSize:500})).records}catch(e){message.value=err(e)}await load()})
</script><style scoped>
.page-shell{height:100%;overflow:auto;padding:24px;background:transparent;color:#172033}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.page-header h2{margin:0;font-size:22px}.page-header p,.modal header p{margin:5px 0 0;color:#7b8495;font-size:13px}.primary,.filters button,.modal footer button{border:0;border-radius:8px;padding:9px 15px;background:#2563eb;color:#fff;font:inherit;font-size:13px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:10px;padding:15px;margin-bottom:14px;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.filters input,.filters select,.body input,.body select{box-sizing:border-box;width:100%;border:1px solid #dfe4ec;border-radius:8px;padding:9px 10px;background:#fff;font:inherit;font-size:13px}.card{overflow:hidden;background:#fff;border:1px solid #e7ebf1;border-radius:12px}.scroll{overflow:auto}table{width:100%;min-width:900px;border-collapse:collapse}th,td{padding:13px 14px;border-bottom:1px solid #eef1f5;text-align:left;font-size:13px}th{background:#fafbfc;color:#687386;font-size:12px}td small{display:block;margin-top:4px;color:#9098a7}.tag{padding:3px 8px;border-radius:5px;background:#eff6ff;color:#1d4ed8}.actions{display:flex;gap:6px}.actions a,.actions button{border:1px solid #dfe4ec;border-radius:7px;background:#fff;padding:6px 9px;color:#4b5565;font-size:12px;text-decoration:none}.state{padding:56px;text-align:center;color:#8992a2}.error{color:#b42336;font-size:13px}.overlay{position:fixed;inset:0;z-index:1200;display:flex;align-items:center;justify-content:center;padding:24px;background:#0f172a6b}.modal{width:min(600px,100%);background:#fff;border-radius:14px}.modal header{display:flex;justify-content:space-between;padding:20px 22px;border-bottom:1px solid #eef1f5}.modal h3{margin:0}.modal header button{border:0;background:none;font-size:24px}.body{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:20px 22px}.body label{display:flex;flex-direction:column;gap:6px}.body label span{color:#687386;font-size:12px}.body :disabled{background:#f5f6f8}.modal footer{display:flex;justify-content:flex-end;gap:8px;padding:15px 22px;border-top:1px solid #eef1f5}.modal footer button:first-child{background:#eef1f6;color:#4b5565}@media(max-width:700px){.filters,.body{grid-template-columns:1fr}}
</style>
